// Generated by scripts/compile-automations.ts from spikes/349-effect-workflow/automations/fix-an-alert.ts (#294 shape). Do not edit.
export const meta = {
	name: "Fix an alert",
	description: "When an alert fires, decides whether to act, has an agent reproduce it as a failing test and fix it, and asks before merging.",
	intent: "fix production alerts before users notice them"
};
export default workflow(async (w, input) => {
	const decision = await w.judge("s1", "Is it worth acting on?", {
		input,
		outcomes: ["act", "ignore"],
		question: "Does this alert hurt real users enough to fix it now?"
	});
	if (decision === "ignore") {
		w.$arm("s3", 0);
		return "ignored";
	} else {
		w.$arm("s3", 1);
	}
	// Reproduce first: no fix lands without a failing test.
	const repro = await w.agent("s4", "Reproduce it as a failing test", { prompt: `Reproduce alert ${input.alertId} (${input.title}) as a failing test. Don't fix anything yet.` });
	const reproduced = await w.judge("s5", "Did it reproduce?", {
		input: repro.text,
		outcomes: ["reproduced", "not reproduced"]
	});
	if (reproduced === "not reproduced") {
		w.$arm("s8", 0);
		await w.ask("s6", `Couldn't reproduce ${input.title}`, {
			question: repro.text,
			options: ["close it", "look again"]
		});
		return "not reproduced";
	} else {
		w.$arm("s8", 1);
	}
	const fix = await w.agent("s9", "Fix it and open a pull request", {
		prompt: "Make the failing test pass, then open a pull request with the trace, the repro and the fix.",
		thread: repro.threadId
	});
	// The deploy pipeline calls this link once the fix is live.
	const deployed = await w.hook("s10", "Deploy callback");
	const answer = await w.ask("s11", `Merge the fix for ${input.title}?`, {
		question: `${fix.pullRequest?.url ?? fix.text}\n\nThe deploy calls ${deployed.path} when it's live.`,
		options: ["merge", "not yet"]
	});
	if (answer !== "merge") {
		w.$arm("s13", 0);
		return "not merged";
	} else {
		w.$arm("s13", 1);
	}
	await w.call("s14", "Merge it", "signalbox.pull_request_action", {
		threadId: fix.threadId,
		url: fix.pullRequest?.url,
		action: "merge"
	});
	const live = await w.waitFor("s15", "Wait for the deploy", {
		on: "hook.called",
		where: { hookId: deployed.hookId },
		timeout: { minutes: 2 }
	});
	await w.notify("s16", "The fix is merged", `${input.title} (${input.release}): ${live === null ? "no deploy confirmation within 2 minutes" : "it's live"}`);
	return live === null ? "merged, deploy unconfirmed" : "fixed";
});
